('p', 'Bảng trên mô tả đúng bộ trạng thái đang có trong mã nguồn, gồm tám giá trị: <c>waiting</c>, <c>confirmed</c>, <c>preparing</c>, <c>delivering</c>, <c>ready</c>, <c>done</c>, <c>cancelled</c> và <c>declined</c>. Nhóm cố ý chỉ cho gửi yêu cầu hủy thay vì hủy ngay, vì người bán có thể đã mua nguyên liệu hoặc đã chuẩn bị xong; AntGo không giữ tiền nên cũng không tự hoàn tiền. Thời hạn trả hàng ở server đang đặt tạm là bảy ngày kể từ khi hoàn thành và chưa được chốt, nên nhóm coi đây là giả định chứ không phải quy tắc cuối cùng. Bộ trạng thái này cũng chưa được thống nhất với phía Bán, đây là một trong những hạn chế được bàn ở chương 5.'),
('land',),
('fig', 'st02', ST + 'anh-sua-ST02 Vòng đời việc đã nhận.drawio.png', 'Sơ đồ trạng thái vòng đời của đề nghị nhận việc', True),
('p', 'Vòng đời việc đã nhận có hai điểm khác đơn hàng. Đề nghị chỉ trở thành việc đang làm sau khi người đăng chọn, và khi việc đủ số người cần, các đề nghị còn lại tự chuyển sang Không được chọn để không ai chờ vô thời hạn. Bước Đã báo xong có hạn 24 giờ: nếu người đăng không phản hồi, đề nghị tự chuyển sang Hoàn thành, để người nhận việc không bị treo công sức vì chủ việc im lặng.'),
('endland',),
('tbl', 'ttdn', 'Bảng chuyển trạng thái của đề nghị nhận việc', [1900, 3200, 1500, 3041],
 ['Trạng thái hiện tại', 'Hành động', 'Ai thực hiện', 'Trạng thái mới'],
 [['(chưa có)', 'Gửi đề nghị kèm giới thiệu và khung giờ; mỗi người một đề nghị đang hoạt động cho mỗi việc', 'Người nhận việc', 'Đã gửi đề nghị'],
  ['Đã gửi đề nghị', 'Chọn người; đủ số người cần thì đóng việc', 'Người đăng việc', 'Được chọn'],
  ['Đã gửi đề nghị', 'Từ chối hoặc việc đã đủ người', 'Người đăng việc', 'Không được chọn'],
  ['Đã gửi đề nghị', 'Rút đề nghị', 'Người nhận việc', 'Đã rút đề nghị'],
  ['Được chọn', 'Bắt đầu làm', 'Người nhận việc', 'Đang làm'],
  ['Được chọn hoặc Đang làm', 'Xin hủy kèm lý do (bận, ốm, khác)', 'Người nhận việc', 'Đã hủy'],
  ['Đang làm', 'Báo hoàn thành kèm ghi chú, có thể kèm ảnh', 'Người nhận việc', 'Đã báo xong'],
  ['Đã báo xong', 'Duyệt hoàn thành, hoặc tự hoàn thành sau 24 giờ', 'Người đăng việc, hệ thống', 'Hoàn thành'],
  ['Hoàn thành', 'Xác nhận đã nhận tiền công', 'Người nhận việc', 'Giữ nguyên, ghi ngày nhận tiền']],
 'left'),
('p', 'Địa chỉ chính xác của việc chỉ được trả về khi đề nghị ở một trong bốn trạng thái Được chọn, Đang làm, Đã báo xong hoặc Hoàn thành; với người chưa được chọn, server chỉ trả khu và block. Đây là quy tắc an toàn quan trọng nhất của luồng nhận việc, và là cơ sở cho tiêu chí về địa chỉ ở chương 1. Việc tự hoàn thành sau 24 giờ được tính ngay lúc đọc hoặc ghi một đề nghị thay vì chạy bằng tác vụ định kỳ, để server không cần thêm thành phần nào ngoài API.'),
('p', 'Ngoài hai bảng chuyển trạng thái, nhóm áp dụng thêm các quy tắc sau trong mã nguồn. Giá cuối cùng của đơn do server tính lại từ giá bài, các tùy chọn đã chọn, phí giao, voucher và số lượng, theo giờ đặt, kể cả khi bài đang trong khung giá khuyến mãi theo giờ. Bài giới hạn số lượng trừ kho bằng một thao tác cập nhật có điều kiện, nên hai người đặt cùng lúc món cuối cùng thì chỉ một đơn được tạo. Đơn bị từ chối hoặc hủy thì tồn kho và voucher được trả lại, đơn hoàn thành đủ điều kiện thì được cộng AntXu. Tài khoản nhận chuyển khoản của người bán được chụp lại vào đơn lúc đặt, nên người bán đổi tài khoản sau đó không làm đổi hướng dẫn thanh toán của đơn cũ.'),

# ---------------------------------------------------------------- 3.3
('h2', '3.3. Kiến trúc hệ thống'),
('p', 'AntGo theo mô hình ba lớp: giao diện Angular chạy trên trình duyệt, API Express xử lý nghiệp vụ, và cơ sở dữ liệu MongoDB. Mục này mô tả từng lớp, cách chia thư mục và các nhóm API.'),
('h3', '3.3.1. Kiến trúc tổng thể'),
('p', 'Trình duyệt tải một ứng dụng Angular dạng một trang, sau đó mọi dữ liệu đi qua các đường dẫn bắt đầu bằng <c>/api</c> dưới dạng JSON. Server không tin dữ liệu do trình duyệt gửi lên: mọi yêu cầu đi qua một chuỗi middleware kiểm tra, rồi mới đến lớp xử lý nghiệp vụ và lớp truy cập dữ liệu ({T:lop}).'),
('tbl', 'lop', 'Các lớp của kiến trúc AntGo', [1900, 3300, 4441],
 ['Lớp', 'Công nghệ', 'Nhiệm vụ'],
 [['Giao diện', 'Angular 22, NgModule, tải lười', 'Hiển thị, kiểm tra nhập liệu, gọi API; giữ trạng thái tạm như đơn đang soạn'],
  ['Kết nối', 'HTTP, JSON, cookie phiên, CORS', 'Chuyển dữ liệu giữa trình duyệt và server; cookie chỉ gửi tới địa chỉ client đã khai báo'],
  ['Middleware', 'helmet, cors, giới hạn kích thước, morgan, express-session, express-rate-limit, zod', 'Đặt tiêu đề bảo mật, ghi log, nạp phiên, giới hạn số lần gọi, kiểm tra dữ liệu đầu vào'],
  ['Nghiệp vụ', 'Router, service theo từng nhóm tài nguyên', 'Áp ràng buộc trạng thái, tính tiền, trừ kho, phân quyền xem dữ liệu'],
  ['Dữ liệu', 'MongoDB, Mongoose', 'Lưu bản ghi theo schema, đánh chỉ mục, khóa duy nhất']],
 'left'),
('p', 'Thứ tự các middleware có ý nghĩa: phiên đăng nhập được nạp trước các router, và kiểm tra dữ liệu bằng zod diễn ra trước khi vào service, nên service luôn làm việc với dữ liệu đã đúng kiểu. Lỗi từ mọi lớp được gom về một middleware xử lý lỗi, trả về cùng một dạng JSON gồm mã lỗi và thông điệp, để giao diện hiển thị thống nhất. Ở client, một interceptor xử lý chung các yêu cầu gọi API, còn chế độ dữ liệu mẫu được bật mặc định và tắt bằng tham số địa chỉ, nên cả nhóm có thể làm giao diện khi server chưa sẵn sàng.'),
('h3', '3.3.2. Cấu trúc client'),
('p', 'Client được chia theo chức năng để mỗi người làm việc trong một thư mục riêng và các nhóm trang được tải khi cần ({T:cl}).'),
('tbl', 'cl', 'Cấu trúc thư mục rút gọn của client', [2900, 6741],
 ['Thư mục', 'Vai trò'],
 [['<c>core/config, core/models</c>', 'Cấu hình gọi API, địa chỉ server; kiểu dữ liệu dùng chung với server'],
  ['<c>core/services</c>', 'Các service gọi API hoặc dữ liệu mẫu: bài đăng, đơn hàng, đề nghị, Messenger, AntXu, đã lưu, địa chỉ, gợi ý, trợ lý'],
  ['<c>core/guards, core/interceptors</c>', 'Guard đăng nhập, quản trị, người bán, cảnh báo rời form chưa lưu; interceptor gọi API'],
  ['<c>core/utils</c>', 'Hàm dùng chung: ánh xạ dữ liệu từ API, ghép bài với mẫu loại bài, tính giá gợi ý, đếm ngược'],
  ['<c>features/*</c>', 'Mười bảy nhóm trang tải lười: trang chủ, tìm kiếm, bài đăng và việc làm, đơn hàng, Messenger, thông báo, hồ sơ, gian hàng, quản trị, Quay món…'],
  ['<c>shared/components</c>', 'Thành phần giao diện dùng lại: thẻ bài, thẻ việc, giá, ảnh đại diện, khối chuyển khoản QR']],
 'left'),
('p', 'Mỗi nhóm trang trong <c>features</c> là một NgModule tải lười, nên trình duyệt chỉ tải mã của nhóm trang khi người dùng mở đến đó. Các trang cần đăng nhập như đơn hàng, Messenger, thông báo, hồ sơ và AntXu đi qua guard xác thực; không gian Bán còn có guard riêng cho người bán, và API quản trị ở server chỉ cho tài khoản quyền quản trị. Tách <c>services</c> khỏi <c>features</c> giúp cùng một service phục vụ nhiều trang, chẳng hạn trạng thái “đã lưu” được cập nhật ngay trên giao diện rồi hoàn lại nếu server báo lỗi.'),
('h3', '3.3.3. Cấu trúc server'),
('p', 'Server chia theo module nghiệp vụ, mỗi module gồm router, service, schema và phần kiểm tra dữ liệu riêng ({T:sv}).'),
('tbl', 'sv', 'Cấu trúc thư mục rút gọn của server', [2900, 6741],
 ['Thư mục', 'Vai trò'],
 [['<c>src/modules/auth</c>', 'Đăng ký, đăng nhập, OTP, quên mật khẩu, đăng nhập Google'],
  ['<c>src/modules/buyer/*</c>', 'Mười bảy module của không gian Mua và Nhận việc: catalog, order, offer, review, chat, xu, recommend, pricing, assistant…'],
  ['<c>src/modules/admin</c>', 'Quản lý người dùng, bài đăng, báo cáo, thống kê, nhật ký'],
  ['<c>src/modules/shared</c>', 'Schema dùng chung: User, Post, Job, nhật ký quản trị, bộ đếm mã'],
  ['<c>src/middlewares, src/utils</c>', 'Xác thực, kiểm tra dữ liệu, xử lý lỗi; tìm kiếm thông minh, chuẩn hóa chữ, phân trang'],
  ['<c>src/seeds, test</c>', 'Dữ liệu seed và các bộ kiểm thử chạy bằng MongoDB trong bộ nhớ']],
 'left'),
('p', 'Cách chia này cho phép mỗi người trong nhóm phụ trách một module mà ít đụng vào mã của người khác. Phía Bán và Đăng việc chưa có module riêng trên server: các thao tác đẩy đơn sang bước kế tiếp, báo phụ thu và chọn người nhận việc hiện nằm ở nhóm API tạm <c>/api/dev</c>, chỉ bật khi không chạy ở môi trường chính thức, để luồng của người mua vẫn kiểm thử được từ đầu đến cuối.'),
('h3', '3.3.4. Các nhóm API'),
('p', 'API của AntGo theo nguyên tắc REST: mỗi tài nguyên có đường dẫn riêng, phương thức HTTP biểu thị hành động, và mã trạng thái phản ánh kết quả. Các nhóm API chính được liệt kê ở {T:api}; toàn bộ endpoint được mô tả bằng Swagger để người làm giao diện đối chiếu.'),
('tbl', 'api', 'Các nhóm API chính của server', [1900, 2900, 4841],
 ['Nhóm', 'Đường dẫn', 'Nội dung'],
 [['Xác thực', '<c>/api/auth</c>', 'Đăng ký, đăng nhập, đăng xuất, OTP, quên mật khẩu, đăng nhập Google, kiểm tra số điện thoại đã tồn tại'],
  ['Bài đăng, việc làm', '<c>/api/posts, /api/jobs, /api/search</c>', 'Danh sách có lọc và phân trang, chi tiết, tìm kiếm, gợi ý tìm kiếm'],
  ['Đơn hàng', '<c>/api/orders</c>', 'Đặt đơn, danh sách, chi tiết, yêu cầu hủy, yêu cầu trả hàng, duyệt phụ thu, theo dõi giao hàng'],
  ['Đề nghị nhận việc', '<c>/api/offers, /api/jobs/:id/offers</c>', 'Gửi, rút, bắt đầu, báo xong, xin hủy, xác nhận nhận tiền'],
  ['Hỏi đáp, nhắn tin', '<c>/api/jobs/:id/questions, /api/conversations</c>', 'Hỏi đáp công khai, hội thoại và tin nhắn, đánh dấu đã đọc'],
  ['Hồ sơ người dùng', '<c>/api/me/addresses, /api/me/saved, /api/me/xu</c>', 'Sổ địa chỉ, bài đã lưu, sổ AntXu và voucher'],
  ['Đánh giá, báo cáo', '<c>/api/reviews, /api/reports</c>', 'Đánh giá sau hoàn thành, báo cáo vi phạm'],
  ['Gợi ý, trợ lý', '<c>/api/posts/:id/similar, /api/pricing, /api/assistant</c>', 'Bài tương tự, gợi ý cho bạn, gợi ý giá, trợ lý tư vấn'],
  ['Quản trị', '<c>/api/admin</c>', 'Người dùng, bài đăng, báo cáo, thống kê, nhật ký, khóa và mở tài khoản']],
 'left'),
('p', 'Các nhóm API được tách theo tài nguyên thay vì theo màn hình, nên cùng một API đơn hàng phục vụ danh sách, chi tiết và theo dõi giao hàng. Mọi API cần đăng nhập đều qua middleware xác thực; các API công khai như danh sách bài chỉ nạp thêm người dùng khi có phiên, để hiện dữ liệu “của tôi” như bài đã lưu mà không bắt buộc đăng nhập.'),

# ---------------------------------------------------------------- 3.4
('h2', '3.4. Mô hình nghiệp vụ và luồng dữ liệu'),
('p', 'Nhóm mô tả hệ thống ở hai góc nhìn: quy trình nghiệp vụ bằng BPMN, thể hiện ai làm gì theo thứ tự, và luồng dữ liệu bằng DFD, thể hiện dữ liệu đi đâu và được lưu ở đâu. Quy trình tổng quan và ba luồng cốt lõi nằm trong chương; các quy trình còn lại nằm ở Phụ lục A.'),
('h3', '3.4.1. Quy trình nghiệp vụ'),
('p', '{F:bp01} cho thấy vòng đời tổng quát của một thành viên, từ đăng ký đến khi một giao dịch kết thúc hoặc phát sinh vấn đề.'),
('land',),
('fig', 'bp01', BP + 'BP01.png', 'Quy trình tổng quan vòng đời của AntGo', True),
('p', 'Sơ đồ chia làm ba nhánh theo nhu cầu: bán hoặc cho thuê, mua hoặc đặt dịch vụ, đăng hoặc nhận việc. Mỗi nhánh là một quy trình con riêng, nên các sơ đồ chi tiết có thể vẽ độc lập. Điểm cần chú ý là mọi giao dịch đều qua cổng “có vấn đề hoặc vi phạm” ở cuối, trong đó vấn đề giữa hai bên đi sang hậu mãi và tranh chấp, còn vi phạm đi sang quản trị, hai đường xử lý khác nhau do người xử lý khác nhau.'),
('endland',),
('p', 'Luồng đặt hàng ({F:bp07}) là luồng nhiều ràng buộc nhất của không gian Mua.'),
('land',),
('fig', 'bp07', BP + 'BP07.png', 'Quy trình đặt hàng, đặt dịch vụ, báo giá và nghiệm thu', True),
('p', 'Hệ thống kiểm tra tồn hoặc lịch và tính tiền ngay khi nhận yêu cầu đặt, trước khi tạo đơn, để người mua biết ngay đơn có đặt được hay không. Sau khi tạo đơn, người bán có quyền từ chối, và khi đó tồn kho cùng voucher được trả lại. Nhánh báo giá và phụ thu dành cho dịch vụ có giá chưa chốt trước, chẳng hạn giao nhận hộ khi đồ lớn hơn kích thước đã chọn: người mua không đồng ý giá cuối thì đơn hủy, chứ không bị ép thực hiện. Nghiệm thu là bước người mua xác nhận đã nhận và thanh toán trực tiếp, sau đó mới cộng AntXu và mở đánh giá.'),
('endland',),
('p', 'Luồng nhận việc gồm hai quy trình nối tiếp: đăng việc và chọn người ({F:bp09}), rồi thực hiện và nghiệm thu ({F:bp10}).'),
('land',),
('fig', 'bp09', BP + 'BP09.png', 'Quy trình đăng việc, ứng tuyển và chọn người', True),
('p', 'Hệ thống chặn đề nghị trùng và chỉ lộ địa chỉ chính xác cho người đã được chọn, nên người chưa được chọn chỉ thấy khu và block của việc. Khi số người được chọn đạt số người cần, hệ thống đóng việc và từ chối các đề nghị còn lại, thay vì để chúng treo. Nếu chưa đủ người, việc vẫn mở và tiếp tục nhận đề nghị khác.'),
('endland',),
('land',),
('fig', 'bp10', BP + 'BP10.png', 'Quy trình thực hiện việc, nghiệm thu và nhận tiền', True),
('p', 'Điểm đáng chú ý của quy trình này là hạn 24 giờ sau khi người nhận việc báo hoàn thành: người đăng việc có thể duyệt hoặc phản đối, và nếu không phản hồi thì việc tự hoàn thành. Phản đối không đóng việc mà chuyển sang quy trình hậu mãi để quản trị viên xem bằng chứng. Bước cuối cùng là người nhận việc xác nhận đã nhận tiền công; nếu chưa nhận được tiền, trạng thái được giữ nguyên và mở báo cáo, vì AntGo không giữ tiền nên chỉ có thể ghi nhận chứ không thể cưỡng chế thanh toán.'),
('endland',),
('h3', '3.4.2. Luồng dữ liệu'),
('p', 'Sơ đồ ngữ cảnh ({F:dfd00}) xem toàn hệ thống là một khối và cho thấy các tác nhân bên ngoài trao đổi gì với nó.'),
('fig', 'dfd00', DF + 'DFD00.png', 'Sơ đồ luồng dữ liệu mức 0 (ngữ cảnh)', False),
('p', 'Hệ thống chỉ có bốn đối tác bên ngoài: thành viên, quản trị viên, nhà cung cấp SMS và Google. Hai hệ thống ngoài chỉ nhận một loại dữ liệu hẹp, mã OTP hoặc yêu cầu xác thực, và không bao giờ nhận hồ sơ hay đơn hàng, nên thông tin giao dịch của cư dân không rời khỏi AntGo. Chiều ngược lại, kết quả gửi và kết quả xác thực là thứ duy nhất AntGo nhận về từ hai hệ thống này.'),
('fig', 'dfd01', DF + 'DFD01.png', 'Sơ đồ luồng dữ liệu mức 1: các quá trình chính', False),
('p', 'Mức 1 chia hệ thống thành bảy quá trình, mỗi quá trình sở hữu một kho dữ liệu riêng: tài khoản, bài và việc, đơn, đề nghị, hội thoại và đánh giá, sổ Xu, báo cáo. Việc mỗi kho thuộc về một quá trình giúp thấy rõ quá trình nào được phép ghi vào đâu; chẳng hạn chỉ quá trình đơn mua ghi vào kho đơn, còn quá trình AntXu chỉ nhận sự kiện từ đơn rồi tự ghi sổ. Các mũi tên giữa quá trình cho thấy sự phụ thuộc: đơn mua lấy dữ liệu bài từ quá trình bài đăng, và gọi quá trình AntXu để áp voucher. Các sơ đồ mức 2 của bốn quá trình chính nằm ở Phụ lục A.'),

# ---------------------------------------------------------------- 3.5
('h2', '3.5. Thiết kế dữ liệu'),
('p', 'Dữ liệu được thiết kế ở hai mức: mô hình logic đích của toàn hệ thống và schema MongoDB đang chạy.'),
('h3', '3.5.1. Mô hình thực thể liên kết'),
('p', 'Mô hình logic đích ({F:er01}) gồm 24 thực thể, bao gồm cả những thực thể nhóm mới đề xuất cho phía Bán như xác minh người bán, thay đổi đơn, khiếu nại giao dịch và xác nhận thanh toán. Schema MongoDB đang chạy ở server hiện có 16 collection, trình bày ở Phụ lục A.'),
('fig', 'er01', ER + 'ER01.png', 'Mô hình thực thể liên kết logic của AntGo', False),
('p', 'Mô hình dùng ký hiệu chân quạ, và quan hệ đa hình như đánh giá hay thông báo trỏ tới nhiều loại đối tượng được vẽ bằng nét đứt, vì MongoDB không có khóa ngoại để ràng buộc loại đối tượng. Dữ liệu con luôn đi cùng cha, chẳng hạn các nhóm tùy chọn món và câu hỏi riêng của bài, được nhúng thẳng vào tài liệu cha thay vì tách thành thực thể. Ngược lại, đơn tham chiếu tới người mua, người bán và bài bằng khóa ngoại, và lưu thêm một bản chụp thông tin bài lúc đặt, để sửa hoặc xóa bài sau này không làm đổi đơn đã có. Sổ AntXu được thiết kế dạng nhật ký chỉ ghi thêm, mỗi biến động là một bản ghi, và một bản ghi đảo có thể trỏ về bản ghi bị đảo, nên số dư luôn truy vết được.'),
